ttom:20px}.summary h2{font-size:16px;margin:0 0 5px}.summary p{font-size:12px;color:var(--muted);margin:0}.count{padding:8px 11px;border-radius:8px;background:#ecfdf3;color:var(--green);font-size:11px;font-weight:800;white-space:nowrap}.requirements{display:grid;grid-template-columns:1fr 1fr;gap:10px}.requirement{display:flex;align-items:center;gap:11px;min-height:67px;padding:12px;border:1px solid #eaecf0;border-radius:10px;background:#fff}.requirement:hover{border-color:#b2ddff;background:#f8fbff}.status-icon{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;flex:none;font-size:13px;font-weight:800}.status-icon.ok{background:#dcfae6;color:var(--green)}.status-icon.bad{background:#fee4e2;color:var(--red)}.req-content{min-width:0;flex:1}.req-name{display:block;font-size:12px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.req-detail{display:block;color:var(--muted);font-size:10px;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.req-status{font-size:9px;font-weight:800;letter-spacing:.04em}.req-status.ok{color:var(--green)}.req-status.bad{color:var(--red)}.flash{padding:11px 13px;border-radius:9px;font-size:12px;margin-top:18px}.flash.error{background:#fff1f0;color:var(--red)}.flash.success{background:#ecfdf3;color:var(--green)}.actions{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:25px;padding-top:22px;border-top:1px solid #eaecf0}.note{color:#98a2b3;font-size:10px;line-height:1.5}.button{min-height:43px;display:inline-flex;align-items:center;justify-content:center;padding:0 19px;border-radius:9px;background:var(--blue);color:#fff;text-decoration:none;font-size:12px;font-weight:800;box-shadow:0 5px 12px #175cd32b}.button:hover{background:#1849a9}.button.disabled{background:#98a2b3;box-shadow:none;pointer-events:none}.footer{text-align:center;color:#98a2b3;font-size:10px;margin-top:16px}@media(max-width:640px){.page{padding:20px 13px}.topbar{margin-bottom:22